package gogenerator

import (
	"context"
	"fmt"

	"github.com/dagger/dagger/cmd/codegen/generator"
	"github.com/dagger/dagger/cmd/codegen/introspection"
)

// GenerateLibrary is not supported for Go. The core bindings of
// dagger.io/dagger are generated by dagger-go-sdk-codegen, from
// github.com/dagger/go-sdk (see sdk/go/core/generate.go).
func (g *GoGenerator) GenerateLibrary(ctx context.Context, schema *introspection.Schema, schemaVersion string) (*generator.GeneratedState, error) {
	return nil, fmt.Errorf("go: generate-library is not supported: use dagger-go-sdk-codegen core (github.com/dagger/go-sdk)")
}
